/**
 * MSH - 股權分散表大股東籌碼分析 API
  * Cloudflare Workers Backend
   */

   export interface Env {
     DB: D1Database;
       CACHE?: KVNamespace;
       }

       const CORS_HEADERS = {
         "Access-Control-Allow-Origin": "*",
           "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
             "Access-Control-Allow-Headers": "Content-Type",
               "Content-Type": "application/json; charset=utf-8",
               };

               function jsonResponse(data: unknown, status = 200): Response {
                 return new Response(JSON.stringify(data, null, 2), {
                     status,
                         headers: CORS_HEADERS,
                           });
                           }

                           function errorResponse(message: string, status = 400): Response {
                             return jsonResponse({ error: message }, status);
                             }

                             // ─── Route Handlers ────────────────────────────────────────────────────────

                             /**
                              * GET /api/skill-analysis
                               * 取得最新 Skill 分析結果（起漲潛力標的）
                                * Query params:
                                 *   market: 'twse' | 'tpex' | 'all' (default: all)
                                  *   limit: number (default: 20)
                                   *   date: YYYY-MM-DD (default: latest)
                                    */
                                    async function handleSkillAnalysis(
                                      request: Request,
                                        env: Env
                                        ): Promise<Response> {
                                          const url = new URL(request.url);
                                            const market = url.searchParams.get("market") || "all";
                                              const limit = Math.min(parseInt(url.searchParams.get("limit") || "20"), 50);
                                                const date = url.searchParams.get("date");

                                                  // Check cache
                                                    const cacheKey = `skill:${market}:${limit}:${date || "latest"}`;
                                                      const cached = env.CACHE ? await env.CACHE.get(cacheKey) : null;
                                                        if (cached) {
                                                            return new Response(cached, {
                                                                  headers: { ...CORS_HEADERS, "X-Cache": "HIT" },
                                                                      });
                                                                        }

                                                                          try {
                                                                              let marketFilter = "";
                                                                                  if (market === "twse") {
                                                                                        marketFilter = `AND CAST(sa.stock_code AS INTEGER) BETWEEN 1000 AND 9999
                                                                                                              AND sa.stock_code NOT LIKE '0%'`;
                                                                                                                  } else if (market === "tpex") {
                                                                                                                        marketFilter = `AND CAST(sa.stock_code AS INTEGER) >= 4000`;
                                                                                                                            }
                                                                                                                            
                                                                                                                                const dateFilter = date
                                                                                                                                      ? `AND sa.analysis_date = '${date}'`
                                                                                                                                            : `AND sa.analysis_date = (SELECT MAX(analysis_date) FROM skill_analysis)`;
                                                                                                                                            
                                                                                                                                                const sql = `
                                                                                                                                                      SELECT
                                                                                                                                                              sa.stock_code,
                                                                                                                                                                      si.stock_name,
                                                                                                                                                                              si.market,
                                                                                                                                                                                      si.industry,
                                                                                                                                                                                              sa.analysis_date,
                                                                                                                                                                                                      sa.skill_score,
                                                                                                                                                                                                              sa.big_holder_ratio,
                                                                                                                                                                                                                      sa.big_holder_trend,
                                                                                                                                                                                                                              sa.retail_trend,
                                                                                                                                                                                                                                      sa.holder_change,
                                                                                                                                                                                                                                              sa.latest_week_change,
                                                                                                                                                                                                                                                      sa.alert
                                                                                                                                                                                                                                                            FROM skill_analysis sa
                                                                                                                                                                                                                                                                  LEFT JOIN stock_info si ON sa.stock_code = si.stock_code
                                                                                                                                                                                                                                                                        WHERE 1=1 ${dateFilter} ${marketFilter}
                                                                                                                                                                                                                                                                              ORDER BY sa.skill_score DESC, sa.alert DESC
                                                                                                                                                                                                                                                                                    LIMIT ${limit}
                                                                                                                                                                                                                                                                                        `;
                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                            const result = await env.DB.prepare(sql).all();
                                                                                                                                                                                                                                                                                                const responseData = {
                                                                                                                                                                                                                                                                                                      meta: {
                                                                                                                                                                                                                                                                                                              market,
                                                                                                                                                                                                                                                                                                                      limit,
                                                                                                                                                                                                                                                                                                                              count: result.results?.length || 0,
                                                                                                                                                                                                                                                                                                                                      analysis_date: result.results?.[0]?.analysis_date || null,
                                                                                                                                                                                                                                                                                                                                              generated_at: new Date().toISOString(),
                                                                                                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                                                                                                          data: result.results || [],
                                                                                                                                                                                                                                                                                                                                                              };
                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                  const responseText = JSON.stringify(responseData);
                                                                                                                                                                                                                                                                                                                                                                      if (env.CACHE) await env.CACHE.put(cacheKey, responseText, { expirationTtl: 3600 });
                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                          return new Response(responseText, { headers: CORS_HEADERS });
                                                                                                                                                                                                                                                                                                                                                                            } catch (err) {
                                                                                                                                                                                                                                                                                                                                                                                console.error("handleSkillAnalysis error:", err);
                                                                                                                                                                                                                                                                                                                                                                                    return errorResponse("Database query failed", 500);
                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                      /**
                                                                                                                                                                                                                                                                                                                                                                                       * GET /api/distribution/:stockCode
                                                                                                                                                                                                                                                                                                                                                                                        * 取得單一股票的歷史持股分布（最近12週）
                                                                                                                                                                                                                                                                                                                                                                                         */
                                                                                                                                                                                                                                                                                                                                                                                         async function handleDistribution(
                                                                                                                                                                                                                                                                                                                                                                                           request: Request,
                                                                                                                                                                                                                                                                                                                                                                                             env: Env,
                                                                                                                                                                                                                                                                                                                                                                                               stockCode: string
                                                                                                                                                                                                                                                                                                                                                                                               ): Promise<Response> {
                                                                                                                                                                                                                                                                                                                                                                                                 if (!stockCode || !/^\d{4}[A-Z]?$/.test(stockCode)) {
                                                                                                                                                                                                                                                                                                                                                                                                     return errorResponse("Invalid stock code");
                                                                                                                                                                                                                                                                                                                                                                                                       }
                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                         const cacheKey = `dist:${stockCode}`;
                                                                                                                                                                                                                                                                                                                                                                                                           const cached = env.CACHE ? await env.CACHE.get(cacheKey) : null;
                                                                                                                                                                                                                                                                                                                                                                                                             if (cached) {
                                                                                                                                                                                                                                                                                                                                                                                                                 return new Response(cached, {
                                                                                                                                                                                                                                                                                                                                                                                                                       headers: { ...CORS_HEADERS, "X-Cache": "HIT" },
                                                                                                                                                                                                                                                                                                                                                                                                                           });
                                                                                                                                                                                                                                                                                                                                                                                                                             }
                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                               try {
                                                                                                                                                                                                                                                                                                                                                                                                                                   const sql = `
                                                                                                                                                                                                                                                                                                                                                                                                                                         SELECT
                                                                                                                                                                                                                                                                                                                                                                                                                                                 hd.date,
                                                                                                                                                                                                                                                                                                                                                                                                                                                         hd.bracket,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 hd.holders,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                         hd.shares,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 hd.ratio,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         si.stock_name
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               FROM holder_distribution hd
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     LEFT JOIN stock_info si ON hd.stock_code = si.stock_code
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           WHERE hd.stock_code = ?
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 AND hd.date IN (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         SELECT DISTINCT date FROM holder_distribution
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 WHERE stock_code = ?
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         ORDER BY date DESC
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 LIMIT 12
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             ORDER BY hd.date DESC, hd.bracket ASC
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 `;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     const result = await env.DB.prepare(sql).bind(stockCode, stockCode).all();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         // 整理為週別分組
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             const byDate: Record<string, unknown[]> = {};
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 let stockName = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     for (const row of result.results || []) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const r = row as Record<string, unknown>;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 const d = r.date as string;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       if (!byDate[d]) byDate[d] = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             byDate[d].push(r);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if (!stockName && r.stock_name) stockName = r.stock_name as string;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const weeks = Object.entries(byDate)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 .sort(([a], [b]) => b.localeCompare(a))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       .map(([date, brackets]) => ({ date, brackets }));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const responseData = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 stock_code: stockCode,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       stock_name: stockName,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             weeks_count: weeks.length,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   data: weeks,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const responseText = JSON.stringify(responseData);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               if (env.CACHE) await env.CACHE.put(cacheKey, responseText, { expirationTtl: 1800 });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   return new Response(responseText, { headers: CORS_HEADERS });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     } catch (err) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         console.error("handleDistribution error:", err);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             return errorResponse("Database query failed", 500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               /**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                * GET /api/top-changes
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 * 取得本週持股變化最大的股票（大股東買超排行）
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  async function handleTopChanges(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    request: Request,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      env: Env
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ): Promise<Response> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const url = new URL(request.url);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const type = url.searchParams.get("type") || "increase"; // increase | decrease
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const limit = Math.min(parseInt(url.searchParams.get("limit") || "20"), 50);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const cacheKey = `topchanges:${type}:${limit}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const cached = env.CACHE ? await env.CACHE.get(cacheKey) : null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (cached) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return new Response(cached, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            headers: { ...CORS_HEADERS, "X-Cache": "HIT" },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const orderDir = type === "increase" ? "DESC" : "ASC";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const sql = `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  SELECT
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          sa.stock_code,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  si.stock_name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          si.market,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  sa.big_holder_trend,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          sa.latest_week_change,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  sa.skill_score,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          sa.alert,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  sa.analysis_date
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        FROM skill_analysis sa
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              LEFT JOIN stock_info si ON sa.stock_code = si.stock_code
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    WHERE sa.analysis_date = (SELECT MAX(analysis_date) FROM skill_analysis)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ORDER BY sa.latest_week_change ${orderDir}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                LIMIT ${limit}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    `;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const result = await env.DB.prepare(sql).all();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const responseData = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  meta: { type, limit, count: result.results?.length || 0 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        data: result.results || [],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const responseText = JSON.stringify(responseData);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (env.CACHE) await env.CACHE.put(cacheKey, responseText, { expirationTtl: 3600 });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return new Response(responseText, { headers: CORS_HEADERS });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } catch (err) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return errorResponse("Database query failed", 500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                /**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 * GET /api/search?q=keyword
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  * 搜尋股票
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   async function handleSearch(request: Request, env: Env): Promise<Response> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     const url = new URL(request.url);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       const q = url.searchParams.get("q") || "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (q.length < 1) return errorResponse("Query too short");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               const sql = `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     SELECT stock_code, stock_name, market, industry
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           FROM stock_info
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 WHERE stock_code LIKE ? OR stock_name LIKE ?
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       LIMIT 20
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           `;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               const pattern = `%${q}%`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const result = await env.DB.prepare(sql).bind(pattern, pattern).all();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       return jsonResponse({ data: result.results || [] });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         } catch (err) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             return errorResponse("Search failed", 500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               /**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                * GET /api/stats
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 * 系統統計數據
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  async function handleStats(env: Env): Promise<Response> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const sql = `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              SELECT
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      (SELECT COUNT(DISTINCT stock_code) FROM holder_distribution) as total_stocks,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              (SELECT COUNT(DISTINCT date) FROM holder_distribution) as total_weeks,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      (SELECT MAX(date) FROM holder_distribution) as latest_date,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              (SELECT MIN(date) FROM holder_distribution) as earliest_date,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      (SELECT COUNT(*) FROM skill_analysis
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               WHERE analysis_date = (SELECT MAX(analysis_date) FROM skill_analysis)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        AND alert = 1) as alert_count
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            `;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const result = await env.DB.prepare(sql).first();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return jsonResponse({ data: result });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } catch (err) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return errorResponse("Stats query failed", 500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // ─── Main Router ────────────────────────────────────────────────────────────
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
/**
 * POST /api/upload-csv
 * 手動上傳 TDCC 股權分散表 CSV 並匯入 D1
 * 接受 multipart/form-data，欄位 "file" (CSV) + 可選 "date" (YYYYMMDD)
 */
async function handleUploadCsv(
  request: Request,
  env: Env
): Promise<Response> {
  try {
    // 只允許 POST
    if (request.method !== "POST") {
      return jsonResponse({ error: "Method Not Allowed" }, 405);
    }

    const contentType = request.headers.get("content-type") || "";
    if (!contentType.includes("multipart/form-data") && !contentType.includes("text/csv") && !contentType.includes("application/octet-stream")) {
      return jsonResponse({ error: "請以 multipart/form-data 上傳 CSV 檔案，欄位名稱為 'file'" }, 400);
    }

    let csvText = "";
    let dateStr = "";

    if (contentType.includes("multipart/form-data")) {
      const formData = await request.formData();
      const file = formData.get("file");
      if (!file || typeof file === "string") {
        return jsonResponse({ error: "找不到 'file' 欄位，請上傳 CSV 檔案" }, 400);
      }
      csvText = await (file as File).text();
      dateStr = (formData.get("date") as string) || "";
    } else {
      csvText = await request.text();
      const url = new URL(request.url);
      dateStr = url.searchParams.get("date") || "";
    }

    if (!csvText.trim()) {
      return jsonResponse({ error: "CSV 內容為空" }, 400);
    }

    // 解析 CSV 行
    const lines = csvText.trim().split("\n");
    const rows = lines.map(l => l.split(",").map(c => c.trim().replace(/^"|"$/g, "")));

    // 偵測 header 行 (若第一行第一欄不是日期格式)
    let dataRows = rows;
    const firstCell = rows[0]?.[0] || "";
    const isHeader = !/^\d{8}$/.test(firstCell) && !/^\d{4}$/.test(firstCell);
    if (isHeader) dataRows = rows.slice(1);

    // 確定欄位 index (opendata 格式: date, stock_code, bracket, holders, shares, ratio)
    // 若有 header 則根據欄名對應
    let dateCol = 0, stockCol = 1, bracketCol = 2, holdersCol = 3, sharesCol = 4, ratioCol = 5;

    if (isHeader) {
      const header = rows[0].map(h => h.toLowerCase());
      const findCol = (names: string[]) => names.reduce((found, n) => found >= 0 ? found : header.findIndex(h => h.includes(n)), -1);
      const d = findCol(["date", "日期", "scadate"]);
      const s = findCol(["stock_code", "證券代號", "code"]);
      const b = findCol(["bracket", "持股分級", "持股"]);
      const h = findCol(["holders", "人數"]);
      const sh = findCol(["shares", "股數"]);
      const r = findCol(["ratio", "比例", "佔"]);
      if (d >= 0) dateCol = d;
      if (s >= 0) stockCol = s;
      if (b >= 0) bracketCol = b;
      if (h >= 0) holdersCol = h;
      if (sh >= 0) sharesCol = sh;
      if (r >= 0) ratioCol = r;
    }

    // 若未提供 date 參數，從資料中取得
    if (!dateStr && dataRows.length > 0) {
      const firstDate = dataRows[0][dateCol];
      if (/^\d{8}$/.test(firstDate)) dateStr = firstDate;
    }
    if (!dateStr) {
      const today = new Date();
      dateStr = today.toISOString().slice(0,10).replace(/-/g,"");
    }

    // 批次寫入 D1 (每次 5 筆)
    let inserted = 0;
    let errors = 0;
    const batchSize = 5;

    for (let i = 0; i < dataRows.length; i += batchSize) {
      const batch = dataRows.slice(i, i + batchSize).filter(r => r.length > Math.max(stockCol, holdersCol, sharesCol));
      if (batch.length === 0) continue;

      const placeholders = batch.map(() => "(?, ?, ?, ?, ?, ?)").join(", ");
      const sql = `INSERT INTO distributions (stock_code, date, bracket, holders, shares, ratio)
        VALUES ${placeholders}
        ON CONFLICT(stock_code, date, bracket) DO UPDATE SET
        holders=excluded.holders, shares=excluded.shares, ratio=excluded.ratio`;

      const params: (string | number)[] = [];
      for (const row of batch) {
        const code = (row[stockCol] || "").padStart(4, "0").substring(0, 6);
        const date = /^\d{8}$/.test(row[dateCol]) ? row[dateCol] : dateStr;
        const bracket = row[bracketCol] || "";
        const holders = parseInt((row[holdersCol] || "0").replace(/,/g, "")) || 0;
        const shares = parseInt((row[sharesCol] || "0").replace(/,/g, "")) || 0;
        const ratio = parseFloat((row[ratioCol] || "0").replace(/,/g, "")) || 0;
        params.push(code, date, bracket, holders, shares, ratio);
      }

      const result = await env.DB.prepare(sql).bind(...params).run();
      if (result.success) {
        inserted += batch.length;
      } else {
        errors += batch.length;
      }
    }

    return jsonResponse({
      success: true,
      message: `成功匯入 ${inserted} 筆，失敗 ${errors} 筆`,
      date: dateStr,
      total_rows: dataRows.length,
      inserted,
      errors,
    });
  } catch (e) {
    return jsonResponse({ error: "匯入失敗: " + String(e) }, 500);
  }
}

export default {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              async fetch(request: Request, env: Env): Promise<Response> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // CORS preflight
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (request.method === "OPTIONS") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return new Response(null, { headers: CORS_HEADERS });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const url = new URL(request.url);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const path = url.pathname;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Route matching
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (path === "/api/skill-analysis" || path === "/api/skill-analysis/") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return handleSkillAnalysis(request, env);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (path === "/api/top-changes" || path === "/api/top-changes/") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return handleTopChanges(request, env);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (path === "/api/search" || path === "/api/search/") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return handleSearch(request, env);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (path === "/api/stats" || path === "/api/stats/") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return handleStats(env);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
        // CSV 手動上傳
        if (path === "/api/upload-csv" || path === "/api/upload-csv/") {
          return handleUploadCsv(request, env);
        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Distribution: /api/distribution/2303
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const distMatch = path.match(/^\/api\/distribution\/([A-Z0-9]+)$/i);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (distMatch) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return handleDistribution(request, env, distMatch[1].toUpperCase());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // Health check
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (path === "/" || path === "/api") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return jsonResponse({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                service: "MSH API",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        version: "1.0.0",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                description: "股權分散表大股東籌碼分析 API",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        endpoints: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "GET /api/skill-analysis?market=twse|tpex|all&limit=20",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "GET /api/distribution/:stockCode",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "GET /api/top-changes?type=increase|decrease&limit=20",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "GET /api/search?q=keyword",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "GET /api/stats",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return errorResponse("Not found", 404);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  };
